// The four program logos Connor designed (Amplified AI Accelerator, Team Plan, Agent Plan, Insiders),
// for the www pages' string-render pattern.
//
// PORTED FROM CONNOR'S `ProgramLogo.tsx` ("Generated from the logo source on November 11, 2026. The
// paths are outlined artwork, so don't edit them by hand."). `PROGRAMS`, the types and `ART` below are
// that file's, byte for byte (a test pins the artwork); only its React render function is replaced by
// `programLogo()`, which returns the same SVG as a string. The README that came with it:
//
//   - variants: "symbol" (24px default), "lockup" (horizontal, 28px type), "stacked" (28px type), "tile"
//     (64px, Forest). `size` is the width for symbols and tiles, the type size for lockups.
//   - letters, people and structure are `currentColor`; the signal is `var(--signal, currentColor)`,
//     so an inline logo takes the section's theme: Energy Bright on Black ("-dark"), Energy on Bone
//     ("-light"). Tiles keep their own colours.
//   - `title` is the accessible name, the program name by default; pass "" when the name is written
//     right next to the logo, and the SVG is hidden from screen readers instead.
//   - never below 16px (symbols), 18px type (lockups) or 32px (tiles); never recoloured, never on
//     Energy or Energy Bright, never retyped as a fake lockup.
//
// No dependencies: the homepage, and the shared Programs menu once it takes these (a follow-up), are
// strings. Every attribute value is escaped.

import { esc } from '../ai101/render';

export type ProgramKey = "accelerator" | "team-plan" | "agent-plan" | "insiders";
export type ProgramLogoVariant = "symbol" | "lockup" | "stacked" | "tile";

type Mark = { ink: string; signal: string };
type Lockup = Mark & { viewBox: [number, number, number, number]; mark: string; letters: Array<[string, string]> };
type Art = { name: string; symbol: Mark; tile: Mark; lockup: Lockup; stacked: Lockup };

/** The four programs in menu order, with the one-line descriptors for the Programs menu. */
