export interface ProgramLogoOptions {
  /** "symbol" (default), "lockup" (horizontal), "stacked" or "tile". */
  variant?: ProgramLogoVariant;
  /** Symbol and tile: width in px (24 and 64 by default). Lockups: the type size in px (28 by default). */
  size?: number;
  /** Accessible name. Defaults to the program name. Pass "" when the name is already next to it. */
  title?: string;
  className?: string;
  /** Extra inline style, after the component's own `display:block;flex:none`. */
  style?: string;
}

const round = (n: number) => Math.round(n * 100) / 100;

/** The component's `a11y()`: a named image, or hidden when the name is written beside it. */
function a11y(name: string, title?: string): string {
  const text = title === undefined ? name : title;
  return text ? ` role="img" aria-label="${esc(text)}"` : ' aria-hidden="true"';
}

const path = (attrs: string, d: string) => `<path${attrs} d="${d}"></path>`;
const signalFill = ` style="fill:${SIGNAL}"`;

/** A program's logo as an SVG string: the same markup `<ProgramLogo>` renders. */
export function programLogo(program: ProgramKey, { variant = 'symbol', size, title, className, style }: ProgramLogoOptions = {}): string {
  const art = ART[program];
  const open = (viewBox: string, width: number, height: number) =>
    `<svg xmlns="http://www.w3.org/2000/svg"${className ? ` class="${esc(className)}"` : ''} style="display:block;flex:none${
      style ? `;${esc(style)}` : ''
    }"${a11y(art.name, title)} viewBox="${viewBox}" width="${width}" height="${height}">`;

  if (variant === 'tile') {
    const px = size ?? 64;
    return `${open('0 0 64 64', px, px)}${path(' fill="#1f4d40"', TILE_GROUND)}<g transform="${TILE_MARK}">${path(' fill="#f5f5f2"', art.tile.ink)}${path(
      ' fill="#6fd3a5"',
      art.tile.signal,
    )}</g></svg>`;
  }

  if (variant === 'lockup' || variant === 'stacked') {
    const g = art[variant];
    const type = size ?? 28;
    const letters = g.letters.map(([transform, d]) => path(` fill="currentColor" transform="${transform}"`, d)).join('');
    return `${open(g.viewBox.join(' '), round((g.viewBox[2] * type) / 1000), round((g.viewBox[3] * type) / 1000))}<g transform="${g.mark}">${path(
      ' fill="currentColor"',
      g.ink,
    )}${path(signalFill, g.signal)}</g>${letters}</svg>`;
  }

  const px = size ?? 24;
  return `${open('0 0 48 48', px, px)}${path(' fill="currentColor"', art.symbol.ink)}${path(signalFill, art.symbol.signal)}</svg>`;
}
